const fs = require("fs");
const path = require("path");
const base = process.cwd();
const files = ["a.txt", "b.txt", "c.txt"];
const nums = [];
for (const f of files) {
  const abs = path.join(base, f);
  const raw = fs.readFileSync(abs, "utf8");
  const matches = raw.match(/-?\d+(?:\.\d+)?/g) || [];
  if (matches.length !== 1) throw new Error(`${f}: expected exactly 1 number, got ${matches.length}`);
  const n = Number(matches[0]);
  if (!Number.isFinite(n)) throw new Error(`${f}: non-finite population ${matches[0]}`);
  console.log(`${abs} | raw=${JSON.stringify(raw.trim())} | population=${n}`);
  nums.push(n);
}
const recomputed = nums.reduce((s, n) => s + n, 0);
console.log(`operands: ${nums.join(" + ")} = ${recomputed}`);

const answerPath = path.join(base, "answer.json");
const answer = JSON.parse(fs.readFileSync(answerPath, "utf8"));
console.log(`answer.json keys: ${JSON.stringify(Object.keys(answer))}`);
if (typeof answer.total !== "number") throw new Error(`typeof total is ${typeof answer.total}, expected number`);
console.log(`total=${answer.total} typeof=${typeof answer.total}`);
if (answer.total !== recomputed) throw new Error(`MISMATCH: answer.total=${answer.total} recomputed=${recomputed}`);
console.log("ASSERTION PASSED: answer.json total === recomputed sum from a.txt, b.txt, c.txt");
' ; echo "exit=$?"
